CREATE OR REPLACE FUNCTION public.execution_activity_trigger() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE n jsonb:=to_jsonb(NEW); BEGIN INSERT INTO public.activity_events(org_id,workspace_id,entity_type,entity_id,actor_id,action,metadata) VALUES(NEW.org_id,NEW.workspace_id,CASE WHEN TG_TABLE_NAME='execution_notes' THEN n->>'entity_type' ELSE TG_TABLE_NAME END,CASE WHEN TG_TABLE_NAME='execution_notes' THEN (n->>'entity_id')::uuid ELSE NEW.id END,auth.uid(),lower(TG_OP),jsonb_build_object('title',n->>'title','status',n->>'status','kind',n->>'kind')); RETURN NEW; END $$;